<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';require __DIR__.'/_auth.php';if(saas_admin())redirect('saas/index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=mb_strtolower(trim($_POST['email']??''));$pass=(string)($_POST['password']??'');$rateKey='saas-login:'.client_ip().':'.$email;$limit=\App\Core\RateLimiter::hit($rateKey,(int)env('RATE_LIMIT_LOGIN_ATTEMPTS',5),(int)env('RATE_LIMIT_LOGIN_WINDOW',300));if(!$limit['allowed']){$error='Muitas tentativas de acesso. Aguarde alguns minutos e tente novamente.';}else{$st=db()->prepare("SELECT * FROM saas_admins WHERE email=:e AND active=1");$st->execute(['e'=>$email]);$a=$st->fetch();if($a&&password_verify($pass,$a['password_hash'])){\App\Core\RateLimiter::clear($rateKey);session_regenerate_id(true);$_SESSION['saas_admin_id']=$a['id'];redirect('saas/index.php');}$error='Credenciais inválidas.';}}layout('Administração SaaS',function()use($error){?><div class="auth-form-wrap" style="min-height:100vh"><form method="post" class="auth-form card"><a class="brand" href="<?=e(url())?>"><span class="brand-mark">P</span><span>PsicoManager <b>AI</b></span></a><h1>Administração SaaS</h1><p>Área exclusiva do proprietário do serviço. Não exibe conteúdo clínico.</p><?php if($error):?><div class="error-box"><?=e($error)?></div><?php endif?><?=csrf_field()?><div class="form-grid"><div class="field"><label>E-mail</label><input type="email" name="email" required></div><div class="field"><label>Senha</label><input type="password" name="password" required></div><button class="button">Entrar</button></div></form></div><?php },['public'=>true]);
